-- Schema for the Quran learning app
create table if not exists surahs (
  n integer primary key,
  arabic text not null,
  translit text not null,
  meaning text not null,
  verses integer not null,
  type text not null,
  snapshot text not null,
  facts jsonb not null,
  key_knowledge jsonb not null,
  respect text not null,
  quiz jsonb not null
);

-- Public read access (content is public, no login needed to browse)
alter table surahs enable row level security;
create policy "Anyone can read surahs" on surahs for select using (true);

-- Progress tracking, tied to a signed-in user, for cross-device sync later
create table if not exists user_progress (
  id uuid default gen_random_uuid() primary key,
  user_id uuid references auth.users not null,
  surah_n integer references surahs(n) not null,
  layers_seen integer[] default '{}',
  quiz_score integer,
  quiz_total integer,
  completed_at timestamptz,
  updated_at timestamptz default now(),
  unique(user_id, surah_n)
);

alter table user_progress enable row level security;
create policy "Users manage their own progress" on user_progress
  for all using (auth.uid() = user_id);

-- Seed data
on conflict (n) do update set
  arabic = excluded.arabic, translit = excluded.translit, meaning = excluded.meaning,
  verses = excluded.verses, type = excluded.type, snapshot = excluded.snapshot,
  facts = excluded.facts, key_knowledge = excluded.key_knowledge, respect = excluded.respect, quiz = excluded.quiz;
