insert into surahs (n, arabic, translit, meaning, verses, type, snapshot, facts, key_knowledge, respect, quiz) values
(114, 'سُورَة النَّاس', 'An-Nas', 'Mankind', 6, 'Meccan', 'An-Nas closes the Quran as its 114th and final chapter. Its six verses were revealed in Makkah, and it is always paired in memory and recitation with the surah just before it, Al-Falaq — together known as Al-Mu''awwidhatayn, "the two chapters of seeking refuge."', '["The word \"an-Nas\" (mankind) appears five times across just six verses — a repetition that keeps circling back to who the surah is addressing.","It''s one of the shortest chapters in the Quran, alongside Al-Kawthar and Al-Asr.","Because it''s the very last chapter, some describe the Quran as opening with a request for guidance (Al-Fatihah) and closing with a request for protection (An-Nas) — a kind of narrative bookend."]'::jsonb, '["The surah is a short, focused prayer. It asks for refuge in three linked descriptions of Allah — as Rabb (Lord), Malik (King), and Ilah (God) of mankind — specifically from the quiet, whispering pull toward harm, whether that whisper comes from Satan or from other people.","Its structure moves from naming who is being sought as protector, to naming exactly what is being sought protection from — an internal, quiet kind of harm rather than an external, visible one."]'::jsonb, 'An-Nas and Al-Falaq are commonly recited together, often as part of a nightly routine before sleep, as chapters associated with seeking protection.', '[{"prompt":"How many verses does Surah An-Nas have?","options":["3","6","11","20"],"correct":1,"explain":"An-Nas has 6 verses, making it one of the shortest chapters in the Quran."},{"prompt":"What does \"An-Nas\" mean?","options":["The Dawn","The Cave","Mankind","The Table"],"correct":2,"explain":"\"An-Nas\" translates to \"mankind\" or \"the people.\""},{"prompt":"Where was An-Nas revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"An-Nas is a Meccan surah."},{"prompt":"Which surah is An-Nas most closely paired with?","options":["Al-Fatihah","Al-Falaq","Al-Ikhlas","Al-Kawthar"],"correct":1,"explain":"An-Nas and Al-Falaq are known jointly as Al-Mu''awwidhatayn."},{"prompt":"The surah primarily asks for refuge from what?","options":["Natural disasters","Financial hardship","Whispered temptation toward harm","Illness"],"correct":2,"explain":"The core request is protection from the quiet, whispering pull toward harm."}]'::jsonb),
(113, 'سُورَة الفَلَق', 'Al-Falaq', 'The Daybreak', 5, 'Meccan', 'Al-Falaq is the 113th chapter, sitting directly before An-Nas. Its five verses were revealed in Makkah. Together with An-Nas, it forms Al-Mu''awwidhatayn — read as a pair far more often than either is read alone.', '["\"Falaq\" specifically means daybreak or the crack of dawn — the moment light splits the darkness.","In just five verses, it names four distinct sources of harm to seek refuge from.","It''s the more externally-focused half of the pair: where An-Nas centers on inner whispers, Al-Falaq centers on outward dangers — night, sorcery, envy."]'::jsonb, '["The surah opens by addressing Allah as \"Rabb of daybreak,\" then moves through four specific things refuge is sought from: the evil of what He has created in general, the darkness of night as it settles, those who practice harmful sorcery, and the envy of someone who envies.","The progression moves from the broad (all creation) to the specific (a person''s private envy) — widening out, then narrowing sharply back in."]'::jsonb, 'Al-Falaq is commonly recited alongside An-Nas, often as part of a nightly routine before sleep, as chapters associated with seeking protection.', '[{"prompt":"How many verses does Surah Al-Falaq have?","options":["3","5","6","9"],"correct":1,"explain":"Al-Falaq has 5 verses."},{"prompt":"What does \"Al-Falaq\" mean?","options":["The Cave","The Daybreak","Mankind","The Table"],"correct":1,"explain":"\"Al-Falaq\" refers to daybreak."},{"prompt":"What is Al-Falaq''s position among the 114 chapters?","options":["1st","50th","113th","114th"],"correct":2,"explain":"Al-Falaq is the 113th chapter, directly before An-Nas."},{"prompt":"Which of these is NOT one of the harms named in Al-Falaq?","options":["The darkness of night","Harmful sorcery","Financial loss","Envy of an envier"],"correct":2,"explain":"Financial loss isn''t mentioned in the surah."},{"prompt":"Compared to An-Nas, Al-Falaq''s focus is more on:","options":["Inner whispers","External, outward dangers","Financial guidance","Historical events"],"correct":1,"explain":"Al-Falaq centers on outward dangers, while An-Nas focuses on internal whispers."}]'::jsonb),
(112, 'سُورَة الإخلاص', 'Al-Ikhlas', 'Sincerity', 4, 'Meccan', 'Al-Ikhlas is a four-verse declaration of God''s oneness, widely regarded as one of the most concise theological statements in the Quran.', '["Despite its short length, it''s traditionally described as carrying the weight of a third of the Quran because of how completely it addresses God''s nature.","Its name means \"sincerity\" or \"purity\" — purity of belief in God''s oneness, free of any partner or comparison.","Unlike most short surahs, it contains no imagery, story, or address to a specific audience — just direct statement."]'::jsonb, '["The surah states God is One and self-sufficient, that nothing depends on Him being divisible into parts, and that He was not born nor does He give birth.","It closes by stating nothing is comparable to Him — a direct, compact rejection of the polytheistic and other theological claims common at the time."]'::jsonb, 'Because of how much theology it packs into four lines, Al-Ikhlas is often one of the first surahs children memorize, and one adults return to for reflection.', '[{"prompt":"How many verses does Al-Ikhlas have?","options":["3","4","6","9"],"correct":1,"explain":"Al-Ikhlas has 4 verses."},{"prompt":"What does \"Al-Ikhlas\" mean?","options":["Sincerity","The Dawn","Victory","The City"],"correct":0,"explain":"\"Al-Ikhlas\" means sincerity or purity of belief."},{"prompt":"What is the surah''s central theme?","options":["Historical narrative","God''s absolute oneness","Legal rulings","Nature imagery"],"correct":1,"explain":"The surah is a direct declaration of tawhid, God''s oneness."},{"prompt":"Al-Ikhlas is often said to carry the weight of:","options":["A single verse","A third of the Quran","The whole Quran","One chapter only"],"correct":1,"explain":"Tradition holds it''s equal in weight to a third of the Quran due to its theological density."},{"prompt":"Where was Al-Ikhlas revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Ikhlas is a Meccan surah."}]'::jsonb),
(111, 'سُورَة المسد', 'Al-Masad', 'The Palm Fiber', 5, 'Meccan', 'Al-Masad is a short, pointed surah addressing the open hostility the Prophet faced from an uncle who actively opposed him, early in the Meccan period.', '["It''s one of the few surahs that directly names a specific individual (by a well-known nickname) rather than speaking in general terms.","\"Masad\" refers to the twisted palm-fiber rope described in its closing verse.","It reflects how early and how personal the opposition to the Prophet''s message sometimes was, even from close family."]'::jsonb, '["The surah states that neither wealth nor status will help the person it addresses, and describes a punishment tied to their own hostility.","It''s brief and unflinching — a reminder that the Quran''s earliest chapters sometimes spoke directly to real events unfolding around the Prophet."]'::jsonb, 'This surah touches on real historical conflict; it''s best read as a specific historical record rather than as a general template for judging people today. A knowledgeable teacher can offer more context on its background.', '[{"prompt":"How many verses does Al-Masad have?","options":["3","5","7","11"],"correct":1,"explain":"Al-Masad has 5 verses."},{"prompt":"What does \"Masad\" refer to?","options":["A river","A twisted palm-fiber rope","A mountain","A star"],"correct":1,"explain":"\"Masad\" is the twisted rope described in the surah''s final verse."},{"prompt":"What makes Al-Masad unusual among short surahs?","options":["It has no verses","It names a specific individual","It''s written in a different language","It has no theme"],"correct":1,"explain":"It''s one of the few surahs that names a specific person by nickname."},{"prompt":"Where was Al-Masad revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Masad is a Meccan surah, revealed early in that period."},{"prompt":"The surah suggests that wealth and status:","options":["Guarantee protection","Won''t help the person addressed","Are irrelevant to the Quran","Are praised throughout"],"correct":1,"explain":"The surah states these things won''t help the individual it addresses."}]'::jsonb),
(110, 'سُورَة النصر', 'An-Nasr', 'Divine Support', 3, 'Medinan', 'An-Nasr is a brief surah associated with victory and closure, traditionally linked to the period near the conquest of Makkah and among the last full surahs revealed.', '["At 3 verses, it''s one of the shortest chapters in the Quran.","It describes people entering the faith \"in multitudes,\" reflecting a turning point in the early Muslim community''s growth.","Despite its theme of triumph, its tone is reflective rather than celebratory — it points toward gratitude, not victory for its own sake."]'::jsonb, '["The surah describes divine support and eventual triumph arriving, and people entering the faith in large numbers as a result.","It then instructs turning to glorify and seek forgiveness from God — pairing success directly with humility rather than pride."]'::jsonb, 'Because of its placement near the end of the Prophet''s life, it''s often reflected on as a reminder to stay grounded even during moments of success.', '[{"prompt":"How many verses does An-Nasr have?","options":["3","6","9","12"],"correct":0,"explain":"An-Nasr has just 3 verses."},{"prompt":"Where (in terms of revelation type) was An-Nasr revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":1,"explain":"An-Nasr is a Medinan surah."},{"prompt":"An-Nasr is traditionally associated with:","options":["The Prophet''s birth","The conquest of Makkah and near the end of his life","The first revelation","A solar eclipse"],"correct":1,"explain":"It''s linked to the period around the conquest of Makkah, late in the Prophet''s life."},{"prompt":"After describing triumph, the surah instructs:","options":["Celebration and feasting","Glorifying God and seeking forgiveness","Silence","Building monuments"],"correct":1,"explain":"The surah pairs success with humility — glorifying God and seeking forgiveness."},{"prompt":"What does the surah say happens as a result of this divine support?","options":["People leave the faith","People enter the faith in multitudes","Trade increases","Nothing changes"],"correct":1,"explain":"It describes people entering the faith in large numbers."}]'::jsonb),
(109, 'سُورَة الكافرون', 'Al-Kafirun', 'The Disbelievers', 6, 'Meccan', 'Al-Kafirun draws a clear, direct line between the Prophet''s monotheistic worship and the practices of those who rejected it, addressed straight to "the disbelievers."', '["The phrase \"I do not worship what you worship\" is repeated with variation across the surah, reinforcing the boundary rather than arguing it once.","Its closing line — \"for you is your religion, and for me is mine\" — is one of the most frequently cited verses on religious distinction.","It''s often recited alongside Al-Ikhlas in personal prayer, pairing a statement of identity with a statement of belief."]'::jsonb, '["The surah rejects any compromise in the basic act of worship itself — it isn''t a rejection of coexistence, but a clear statement that worship practices won''t be merged or exchanged.","Its repetitive structure functions like a firm, calm refusal rather than a heated argument."]'::jsonb, 'This surah is sometimes discussed in the context of religious coexistence; its closing line is widely cited, so it''s worth understanding its fuller context from a knowledgeable source rather than the single line alone.', '[{"prompt":"How many verses does Al-Kafirun have?","options":["3","6","9","12"],"correct":1,"explain":"Al-Kafirun has 6 verses."},{"prompt":"What does \"Al-Kafirun\" mean?","options":["The Believers","The Disbelievers","The Poets","The Table"],"correct":1,"explain":"\"Al-Kafirun\" means \"the disbelievers.\""},{"prompt":"The surah is addressed to whom?","options":["The Prophet''s family","Those who rejected the message","Angels","Animals"],"correct":1,"explain":"It''s addressed directly to those who rejected the Prophet''s message."},{"prompt":"The surah''s closing verse is often cited regarding:","options":["Trade law","Religious distinction","Marriage","Farming"],"correct":1,"explain":"\"For you is your religion, and for me is mine\" is widely cited on religious distinction."},{"prompt":"Which surah is Al-Kafirun often recited alongside?","options":["Al-Falaq","An-Nas","Al-Ikhlas","Al-Kawthar"],"correct":2,"explain":"It''s often paired with Al-Ikhlas in personal recitation."}]'::jsonb),
(108, 'سُورَة الكوثر', 'Al-Kawthar', 'Abundance', 3, 'Meccan', 'Al-Kawthar is the shortest chapter in the Quran at just 3 verses, offering reassurance to the Prophet after mockery from opponents.', '["It''s the single shortest surah in the entire Quran.","\"Kawthar\" means abundance, and is often described in tradition as a river or fountain granted in paradise.","It was revealed in response to opponents mocking the Prophet, reportedly over the loss of his sons."]'::jsonb, '["The surah tells the Prophet that abundance has been given to him, then instructs him to pray and offer sacrifice in response.","Its final verse turns the mockery back on the ones who mocked, stating that it''s they, not the Prophet, who will be cut off — an answer to insult with reassurance rather than retaliation."]'::jsonb, 'Interpretations of exactly what "Kawthar" refers to vary somewhat among scholars; the app aims to reflect the most common understanding, not settle every detail.', '[{"prompt":"How many verses does Al-Kawthar have?","options":["3","5","7","9"],"correct":0,"explain":"Al-Kawthar is the shortest surah in the Quran, with 3 verses."},{"prompt":"What does \"Kawthar\" mean?","options":["The Cave","Abundance","The Dawn","Victory"],"correct":1,"explain":"\"Kawthar\" means abundance."},{"prompt":"The surah was revealed in response to:","options":["A military victory","Mockery of the Prophet","A natural disaster","A trade dispute"],"correct":1,"explain":"It responds to opponents mocking the Prophet."},{"prompt":"After stating abundance was given, the surah instructs the Prophet to:","options":["Travel and preach","Pray and offer sacrifice","Remain silent","Fast for a year"],"correct":1,"explain":"The surah instructs prayer and sacrifice as a response."},{"prompt":"Al-Kawthar is notable for being:","options":["The longest surah","The shortest surah","The only Medinan surah","Written in verse form only"],"correct":1,"explain":"It''s the shortest chapter in the Quran."}]'::jsonb),
(107, 'سُورَة الماعون', 'Al-Ma''un', 'Small Kindnesses', 7, 'Meccan', 'Al-Ma''un warns against a specific kind of hypocrisy — outward religious appearance paired with neglect of the vulnerable.', '["It directly criticizes neglecting orphans and failing to encourage feeding the needy.","It describes prayer performed carelessly or for show as a form of failure, not just an incomplete act.","\"Al-Ma''un\" refers to small, everyday acts of neighborly assistance — the very thing the surah says is being withheld."]'::jsonb, '["The surah links sincere belief directly to how someone treats the vulnerable — it doesn''t separate ritual worship from social responsibility.","It criticizes both the careless performer of prayer and the person who shows off their worship while withholding basic kindness from others."]'::jsonb, 'This surah is often referenced as a reminder that worship and everyday kindness are meant to reinforce each other, not stand apart.', '[{"prompt":"How many verses does Al-Ma''un have?","options":["3","5","7","10"],"correct":2,"explain":"Al-Ma''un has 7 verses."},{"prompt":"What does \"Al-Ma''un\" refer to?","options":["Small acts of neighborly kindness","A river","A mountain","A star"],"correct":0,"explain":"\"Al-Ma''un\" refers to small, everyday assistance."},{"prompt":"The surah criticizes neglect of whom specifically?","options":["Travelers","Orphans and the needy","Merchants","Soldiers"],"correct":1,"explain":"It criticizes neglecting orphans and not encouraging feeding the needy."},{"prompt":"According to the surah, what kind of prayer is criticized?","options":["Prayer performed carelessly or for show","Prayer that is too long","Prayer in a group","Silent prayer"],"correct":0,"explain":"The surah criticizes careless or performative prayer."},{"prompt":"The surah''s core theme connects worship to:","options":["Trade success","Social responsibility toward the vulnerable","Military strength","Poetry"],"correct":1,"explain":"It ties sincere worship directly to care for the vulnerable."}]'::jsonb),
(106, 'سُورَة قريش', 'Quraysh', 'Quraysh', 4, 'Meccan', 'This short surah is named directly after the Quraysh, the tribe the Prophet belonged to, and calls them to gratitude for the security and provision they''d long enjoyed.', '["It''s one of the few surahs named directly after a tribe rather than a concept or event.","It references the tribe''s historic winter and summer trade caravans.","It''s closely linked in placement and theme to Al-Fil, the surah just before it."]'::jsonb, '["The surah points to the safety of Quraysh''s trade journeys and the provision that came with them as reasons to worship the \"Lord of this House\" — a reference to the Kaaba.","It frames security and sustenance not as things to take for granted, but as prompts toward gratitude."]'::jsonb, 'Its historical detail about trade caravans is a useful window into daily life in Makkah at the time.', '[{"prompt":"How many verses does Surah Quraysh have?","options":["3","4","6","8"],"correct":1,"explain":"Surah Quraysh has 4 verses."},{"prompt":"Quraysh is named after:","options":["A river","A star","A tribe","A mountain"],"correct":2,"explain":"It''s named directly after the Quraysh tribe."},{"prompt":"The surah references which historical practice?","options":["Farming seasons","Winter and summer trade caravans","Building construction","Poetry competitions"],"correct":1,"explain":"It references the tribe''s seasonal trade journeys."},{"prompt":"Which surah is Quraysh closely linked to?","options":["Al-Kawthar","Al-Fil","Al-Ikhlas","An-Nasr"],"correct":1,"explain":"Quraysh follows and connects thematically to Al-Fil."},{"prompt":"\"Lord of this House\" refers to the Lord of:","options":["A palace","The Kaaba","A market","A fort"],"correct":1,"explain":"The reference is to the Kaaba in Makkah."}]'::jsonb),
(105, 'سُورَة الفيل', 'Al-Fil', 'The Elephant', 5, 'Meccan', 'Al-Fil recounts a historic event: an army advancing on Makkah with elephants, said to have been turned back before reaching the sacred sanctuary.', '["The event is traditionally dated near the Prophet''s birth year, sometimes called \"The Year of the Elephant.\"","The surah describes the army being repelled by birds dropping stones of baked clay.","It''s the shortest narrative-style surah recounting a specific historical event."]'::jsonb, '["The surah frames the event as a demonstration of protection over the sacred sanctuary in Makkah, regardless of the strength of the force sent against it.","Its brevity is part of its style — the event is recounted in just five verses, assuming the listener already knows the broader story."]'::jsonb, 'As with other historical surahs, deeper context on this event is best explored through a knowledgeable teacher or classical commentary.', '[{"prompt":"How many verses does Al-Fil have?","options":["5","8","11","15"],"correct":0,"explain":"Al-Fil has 5 verses."},{"prompt":"What does \"Al-Fil\" mean?","options":["The Elephant","The Bird","The Mountain","The Fire"],"correct":0,"explain":"\"Al-Fil\" means \"the elephant.\""},{"prompt":"The event described is traditionally dated near:","options":["The Prophet''s death","The Prophet''s birth year","The conquest of Makkah","The first revelation"],"correct":1,"explain":"It''s traditionally linked to the so-called \"Year of the Elephant,\" near the Prophet''s birth."},{"prompt":"According to the surah, the army was repelled by:","options":["A flood","Birds dropping stones","A sandstorm","Soldiers"],"correct":1,"explain":"The Quranic account describes birds dropping stones of baked clay."},{"prompt":"The surah''s central theme is:","options":["Trade agreements","Protection of the sacred sanctuary","Farming practices","Poetry"],"correct":1,"explain":"It emphasizes protection over Makkah''s sanctuary."}]'::jsonb),
(104, 'سُورَة الهمزة', 'Al-Humazah', 'The Traducer', 9, 'Meccan', 'Al-Humazah condemns habitual slander and an obsession with counting and hoarding wealth as a false source of security.', '["Its name refers to someone who habitually backbites or mocks others, often behind their back.","It uses vivid imagery of a crushing fire as consequence for this behavior.","It directly critiques the belief that wealth alone can guarantee lasting security."]'::jsonb, '["The surah describes a specific type of person — one who slanders others and constantly counts their wealth, believing it will make them immortal or untouchable.","It counters that belief directly with imagery of consequence, making clear that status and money don''t override accountability."]'::jsonb, 'This surah is often reflected on as a caution against gossip and materialism, both of which remain common temptations.', '[{"prompt":"How many verses does Al-Humazah have?","options":["6","9","12","15"],"correct":1,"explain":"Al-Humazah has 9 verses."},{"prompt":"What does \"Al-Humazah\" refer to?","options":["A habitual slanderer","A trader","A soldier","A poet"],"correct":0,"explain":"\"Al-Humazah\" refers to someone who habitually slanders or mocks others."},{"prompt":"The surah criticizes obsession with:","options":["Farming","Counting and hoarding wealth","Travel","Poetry"],"correct":1,"explain":"It critiques the belief that wealth alone guarantees security."},{"prompt":"What consequence imagery does the surah use?","options":["A flood","A crushing fire","A storm","Darkness"],"correct":1,"explain":"It uses imagery of a crushing fire as consequence."},{"prompt":"Where was Al-Humazah revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Humazah is a Meccan surah."}]'::jsonb),
(103, 'سُورَة العصر', 'Al-Asr', 'The Declining Day', 3, 'Meccan', 'Al-Asr is one of the shortest surahs in the Quran, often cited by scholars as containing the essence of the entire message in just three verses.', '["It''s tied with An-Nasr as one of the shortest chapters, at 3 verses.","Imam Ash-Shafi''i is widely reported to have said that if people reflected on this surah alone, it would be enough for them.","It names exactly four things that save a person from loss — belief, good deeds, encouraging truth, and encouraging patience."]'::jsonb, '["The surah opens with an oath by time (or the declining day), then states that humanity is in loss.","It then narrows to an exception: those who believe, do good deeds, and mutually encourage each other toward truth and patience — a compact framework for a meaningful life."]'::jsonb, 'Its density has made it a favorite for memorization and reflection across all ages, given how much it says in so few words.', '[{"prompt":"How many verses does Al-Asr have?","options":["3","5","8","10"],"correct":0,"explain":"Al-Asr has just 3 verses."},{"prompt":"What does the surah open with an oath by?","options":["The mountains","Time (or the declining day)","The sea","The stars"],"correct":1,"explain":"It opens with an oath by time or the declining day."},{"prompt":"According to the surah, what is humanity''s default state?","options":["Success","Loss","Neutrality","Wealth"],"correct":1,"explain":"The surah states humanity is in loss, with an exception that follows."},{"prompt":"Which of these is NOT one of the four things named as saving from loss?","options":["Belief","Good deeds","Wealth accumulation","Encouraging patience"],"correct":2,"explain":"The four are belief, good deeds, encouraging truth, and encouraging patience — not wealth."},{"prompt":"Al-Asr is often cited as:","options":["The longest surah","A summary of the Quran''s core message","A historical record only","A legal text"],"correct":1,"explain":"It''s widely cited as containing the essence of the Quran''s message despite its brevity."}]'::jsonb),
(102, 'سُورَة التكاثر', 'At-Takathur', 'Rivalry in world increase', 8, 'Meccan', 'At-Takathur warns against becoming consumed by competition for wealth and status, to the point that it distracts from mortality itself.', '["\"Takathur\" describes a rivalry centered on accumulating more — wealth, numbers, status.","The surah states this rivalry continues \"until you visit the graves\" — a blunt reminder of where the competition ends.","It closes by noting people will be questioned about the pleasures they enjoyed."]'::jsonb, '["The surah describes how the drive to accumulate can consume a person''s attention entirely, right up until death.","It then shifts to certainty — that this distraction will eventually be seen clearly, and that people will be asked to account for the comforts they pursued."]'::jsonb, 'A useful surah for reflecting on modern equivalents of this rivalry, from material goods to status online.', '[{"prompt":"How many verses does At-Takathur have?","options":["5","8","11","14"],"correct":1,"explain":"At-Takathur has 8 verses."},{"prompt":"What does \"Takathur\" describe?","options":["Rivalry in accumulating more","A type of prayer","A historical battle","A trade route"],"correct":0,"explain":"\"Takathur\" refers to competitive rivalry in accumulation."},{"prompt":"According to the surah, this rivalry continues until:","options":["Sunset","Visiting the graves","The next trade season","A festival"],"correct":1,"explain":"The surah states this distraction continues \"until you visit the graves.\""},{"prompt":"The surah closes by noting people will be questioned about:","options":["Their ancestry","The pleasures they enjoyed","Their trade partners","Their travels"],"correct":1,"explain":"It closes noting accountability for the comforts pursued."},{"prompt":"Where was At-Takathur revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"At-Takathur is a Meccan surah."}]'::jsonb),
(101, 'سُورَة القارعة', 'Al-Qari''ah', 'The Calamity', 11, 'Meccan', 'Al-Qari''ah describes the Day of Judgment through vivid, almost physical imagery — "the striking hour" that shakes ordinary life apart.', '["Its name, \"the striking\" or \"the calamity,\" is repeated at the very start for emphasis.","It compares people on that day to scattered moths, and mountains to carded (loosened) wool.","Like several short Meccan surahs, it uses natural imagery to make an abstract event feel immediate."]'::jsonb, '["The surah describes the Day of Judgment as an overwhelming, disorienting event using comparisons drawn from everyday life — moths and wool — to make the scale of it graspable.","It then moves to the weighing of deeds, describing two clear outcomes based on whether that weighing tips toward good or not."]'::jsonb, 'The vivid imagery here is meant to prompt reflection, not fear alone — it''s often read alongside other short Judgment-Day surahs for that reason.', '[{"prompt":"How many verses does Al-Qari''ah have?","options":["8","11","14","20"],"correct":1,"explain":"Al-Qari''ah has 11 verses."},{"prompt":"What does \"Al-Qari''ah\" mean?","options":["The Calamity","The Dawn","The Cave","The River"],"correct":0,"explain":"\"Al-Qari''ah\" means the calamity or the striking hour."},{"prompt":"People on that day are compared to:","options":["Falling stars","Scattered moths","Flowing rivers","Standing trees"],"correct":1,"explain":"The surah compares people to scattered moths."},{"prompt":"Mountains are compared to:","options":["Solid rock","Carded (loosened) wool","Glass","Sand dunes"],"correct":1,"explain":"Mountains are compared to carded wool — light and scattered."},{"prompt":"The surah''s central theme involves:","options":["Trade caravans","The weighing of deeds on Judgment Day","Historical battles","Farming cycles"],"correct":1,"explain":"It centers on the Day of Judgment and the weighing of deeds."}]'::jsonb),
(100, 'سُورَة العاديات', 'Al-Adiyat', 'The Courser', 11, 'Meccan', 'Al-Adiyat opens with a vivid oath by charging warhorses, then pivots sharply to a critique of human ingratitude.', '["The opening verses use rhythmic, sound-rich imagery of galloping horses striking sparks from stone.","After the vivid opening, the surah shifts abruptly to describe humanity as ungrateful to its Lord.","It closes with a reminder that what''s hidden in hearts will be brought out and examined."]'::jsonb, '["The surah''s opening oath paints a scene of charging horses in battle, using sound and motion to draw the listener in before shifting tone.","It then turns that vivid energy toward a sober point: that people are often intensely ungrateful, and are themselves witness to that ingratitude, even as they pursue wealth eagerly."]'::jsonb, 'The contrast between vivid imagery and sober message is a good example of how short Meccan surahs often work — pulling attention in before making their point.', '[{"prompt":"How many verses does Al-Adiyat have?","options":["8","11","14","18"],"correct":1,"explain":"Al-Adiyat has 11 verses."},{"prompt":"What does the surah open with an oath by?","options":["Charging warhorses","The sea","The stars","Mountains"],"correct":0,"explain":"It opens with a vivid oath by charging warhorses."},{"prompt":"After its vivid opening, the surah shifts to describe:","options":["A trade agreement","Human ingratitude","A wedding","A harvest"],"correct":1,"explain":"It shifts to critique humanity''s ingratitude."},{"prompt":"The surah closes with a reminder that:","options":["Wealth guarantees safety","What''s hidden in hearts will be revealed","Horses are sacred","Trade should stop"],"correct":1,"explain":"It closes noting that what''s hidden in hearts will be brought out and examined."},{"prompt":"Where was Al-Adiyat revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Adiyat is a Meccan surah."}]'::jsonb),
(99, 'سُورَة الزلزلة', 'Az-Zalzalah', 'The Earthquake', 8, 'Medinan', 'Az-Zalzalah describes a cosmic earthquake at the Day of Judgment, when the earth itself testifies to everything that happened on it.', '["It''s one of the relatively few short, Judgment-Day-themed surahs classified as Medinan rather than Meccan.","It describes the earth \"speaking\" — reporting everything that occurred upon it.","Its closing verses are often quoted for stating that even the smallest deed, atom-sized, will be seen."]'::jsonb, '["The surah describes the earth shaking violently and giving up what''s inside it, then reporting everything as instructed by its Lord.","It closes with one of the Quran''s most quoted lines on accountability — that whoever does even the smallest amount of good or harm will see it."]'::jsonb, 'The closing verses here are widely referenced as a reminder that no act, however small, goes unnoticed.', '[{"prompt":"How many verses does Az-Zalzalah have?","options":["5","8","12","16"],"correct":1,"explain":"Az-Zalzalah has 8 verses."},{"prompt":"Where was Az-Zalzalah revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":1,"explain":"Az-Zalzalah is a Medinan surah, unlike most short Judgment-Day surahs."},{"prompt":"What does the surah describe the earth doing?","options":["Splitting the sky","Testifying to what happened on it","Sinking into the sea","Turning to gold"],"correct":1,"explain":"The earth is described as reporting everything that occurred on it."},{"prompt":"The surah''s closing verses are often quoted for stating:","options":["Wealth guarantees reward","Even the smallest deed will be seen","Time heals all things","Only large deeds matter"],"correct":1,"explain":"It states that even an atom''s weight of good or harm will be seen."},{"prompt":"What does \"Az-Zalzalah\" mean?","options":["The Earthquake","The Fire","The River","The Mountain"],"correct":0,"explain":"\"Az-Zalzalah\" means \"the earthquake.\""}]'::jsonb),
(98, 'سُورَة البينة', 'Al-Bayyinah', 'The Clear Proof', 8, 'Medinan', 'Al-Bayyinah discusses how disbelief persisted among some People of the Book and polytheists even after "clear evidence" came to them, and outlines the core of true worship.', '["It directly addresses both \"People of the Book\" and polytheists in the same breath, a relatively rare structural choice.","It describes core worship in simple terms: sincere devotion, prayer, and charity.","Its closing verses describe the best and worst of creation in terms of belief and conduct, not lineage or status."]'::jsonb, '["The surah opens by noting that disbelief among some groups didn''t end automatically just because clear evidence arrived — belief still required a personal response.","It then defines true worship simply, and closes by contrasting those who reject truth with those who believe and do good, describing the latter as the best of creation."]'::jsonb, 'This surah is often discussed in the context of shared scripture and differing responses to it; deeper theological nuance here is best explored with a knowledgeable teacher.', '[{"prompt":"How many verses does Al-Bayyinah have?","options":["5","8","11","15"],"correct":1,"explain":"Al-Bayyinah has 8 verses."},{"prompt":"Where was Al-Bayyinah revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":1,"explain":"Al-Bayyinah is a Medinan surah."},{"prompt":"What does \"Al-Bayyinah\" mean?","options":["The Clear Proof","The Elephant","The Night","The City"],"correct":0,"explain":"\"Al-Bayyinah\" means \"the clear proof\" or \"clear evidence.\""},{"prompt":"The surah defines core worship as including:","options":["Sincere devotion, prayer, and charity","Trade and farming","Poetry and storytelling","Warfare"],"correct":0,"explain":"It describes sincere devotion, prayer, and charity as core worship."},{"prompt":"The surah''s closing verses contrast people based on:","options":["Wealth","Lineage","Belief and conduct","Geography"],"correct":2,"explain":"It contrasts people based on belief and conduct, not lineage or status."}]'::jsonb),
(97, 'سُورَة القدر', 'Al-Qadr', 'The Power', 5, 'Meccan', 'Al-Qadr describes "the Night of Decree," a night said to be better than a thousand months, closely tied to the revelation of the Quran itself.', '["It''s directly linked to the beginning of the Quran''s revelation, describing the night it began coming down.","It states this single night carries more significance than a thousand months — a striking comparison for just five verses.","It describes angels and the \"Spirit\" descending during that night with permission for every affair."]'::jsonb, '["The surah opens by stating the Quran was sent down during \"the Night of Decree,\" then immediately asks what could convey its significance.","It closes describing that night as one of peace, extending until the break of dawn — a night widely sought out for reflection during its associated period each year."]'::jsonb, 'The exact night is not stated explicitly in the Quran, and its identification is drawn from tradition — worth exploring further with a knowledgeable source if this interests you.', '[{"prompt":"How many verses does Al-Qadr have?","options":["3","5","8","11"],"correct":1,"explain":"Al-Qadr has 5 verses."},{"prompt":"What does \"Al-Qadr\" refer to?","options":["The Night of Decree","The Day of Judgment","A historical battle","A trade route"],"correct":0,"explain":"\"Al-Qadr\" refers to the Night of Decree (or Power)."},{"prompt":"According to the surah, this night is better than:","options":["A single day","A thousand months","A hundred years","One lifetime"],"correct":1,"explain":"The surah states this night is better than a thousand months."},{"prompt":"What event is this night closely tied to?","options":["The conquest of Makkah","The beginning of the Quran''s revelation","The Prophet''s birth","A solar eclipse"],"correct":1,"explain":"It''s tied to the start of the Quran being revealed."},{"prompt":"The surah describes the night as extending until:","options":["Midnight","The break of dawn","Noon","Sunset"],"correct":1,"explain":"It describes the night as peaceful, extending until dawn."}]'::jsonb),
(96, 'سُورَة العلق', 'Al-Alaq', 'The Clot', 19, 'Meccan', 'Al-Alaq''s opening verses are traditionally identified as the very first words revealed to the Prophet, beginning with the command "Read" or "Recite."', '["Its opening five verses are widely held to be the first revelation the Prophet received.","\"Alaq\" refers to a clinging clot, part of a description of early human development.","The surah later shifts to address someone who forbids another from praying — a different scene from its famous opening."]'::jsonb, '["The surah''s first verses instruct reading or reciting in the name of God, describing Him as the one who taught by the pen and taught humanity what it didn''t know.","Later verses shift to address arrogance and obstruction — specifically someone preventing another from prayer — showing the surah covers more than just its well-known opening."]'::jsonb, 'Because its opening holds such historical significance, it''s often one of the first passages people learn about when studying how the Quran''s revelation began.', '[{"prompt":"How many verses does Al-Alaq have?","options":["9","19","25","30"],"correct":1,"explain":"Al-Alaq has 19 verses."},{"prompt":"Al-Alaq''s opening verses are traditionally identified as:","options":["The last revelation","The first revelation","A later addition","Unrelated to revelation history"],"correct":1,"explain":"They''re widely held to be the first words revealed to the Prophet."},{"prompt":"What does \"Alaq\" refer to?","options":["A clinging clot","A star","A river","A mountain"],"correct":0,"explain":"\"Alaq\" refers to a clinging clot, tied to early human development."},{"prompt":"The opening command of the surah is:","options":["Write","Read/Recite","Travel","Fast"],"correct":1,"explain":"The surah opens with the command to read or recite."},{"prompt":"Later in the surah, who does it address?","options":["A trader","Someone preventing another from prayer","A soldier","A poet"],"correct":1,"explain":"Later verses address someone obstructing another person''s prayer."}]'::jsonb),
(95, 'سُورَة التين', 'At-Tin', 'The Fig', 8, 'Meccan', 'At-Tin opens with an oath by the fig and the olive, then reflects on humanity''s creation in the finest form and its potential to fall from that state.', '["Its name comes from the fig, the first thing sworn by in its opening oath.","It also swears by Mount Sinai and \"this secure city,\" widely understood as Makkah.","It states humanity was created in \"the best of forms,\" before describing potential decline."]'::jsonb, '["The surah''s oaths point toward places tied to earlier prophets and revelation, before turning to describe humanity''s creation in the best possible form.","It then notes that people can be reduced to \"the lowest of the low\" — except those who believe and do good, who are promised a reward without end."]'::jsonb, 'A short surah often used to reflect on human potential and the choices that shape which direction a person moves in.', '[{"prompt":"How many verses does At-Tin have?","options":["5","8","11","14"],"correct":1,"explain":"At-Tin has 8 verses."},{"prompt":"What does the surah open with an oath by?","options":["The fig and the olive","The sun and moon","Rivers and seas","Mountains and stars"],"correct":0,"explain":"It opens with an oath by the fig and the olive."},{"prompt":"\"This secure city\" in the surah is widely understood to refer to:","options":["Madinah","Makkah","Jerusalem","Damascus"],"correct":1,"explain":"It''s widely understood as a reference to Makkah."},{"prompt":"According to the surah, humanity was created in:","options":["A flawed state","The best of forms","Darkness","Silence"],"correct":1,"explain":"It states humanity was created in the best of forms."},{"prompt":"Who is excepted from being reduced to \"the lowest of the low\"?","options":["The wealthy","Those who believe and do good","Rulers","No one"],"correct":1,"explain":"Those who believe and do good are excepted from that decline."}]'::jsonb),
(94, 'سُورَة الشرح', 'Ash-Sharh', 'The Relief', 8, 'Meccan', 'Ash-Sharh speaks directly to the Prophet about having his burden eased, and contains the widely known line: "with hardship comes ease."', '["The line \"with hardship comes ease\" appears twice in close succession, reinforcing the point through repetition.","It opens by asking, rhetorically, whether the Prophet''s chest hasn''t been \"expanded\" or opened — a metaphor for relief and capacity.","It''s often read as a companion to the surah before it, Ad-Duha, since both address the Prophet directly during a difficult period."]'::jsonb, '["The surah reassures the Prophet that his burden has been lifted and his difficulties eased, reminding him that hardship and ease arrive close together, not as opposites separated by long stretches.","It closes with an instruction to keep striving and to turn attention toward God once one task is finished — a rhythm of effort followed by devotion."]'::jsonb, 'Its short, reassuring message is often turned to during difficult periods, given how directly it addresses hardship and relief.', '[{"prompt":"How many verses does Ash-Sharh have?","options":["5","8","11","14"],"correct":1,"explain":"Ash-Sharh has 8 verses."},{"prompt":"What well-known line appears twice in this surah?","options":["\"Read in the name of your Lord\"","\"With hardship comes ease\"","\"For you is your religion\"","\"Say, He is God, One\""],"correct":1,"explain":"\"With hardship comes ease\" is repeated in close succession."},{"prompt":"The surah opens by referring to the Prophet''s:","options":["Travels","Expanded chest","Family","Wealth"],"correct":1,"explain":"It opens asking whether his chest hasn''t been expanded — a metaphor for relief."},{"prompt":"Which surah is Ash-Sharh often read alongside?","options":["Al-Fil","Ad-Duha","Al-Kawthar","Quraysh"],"correct":1,"explain":"Ash-Sharh is often paired with Ad-Duha, both addressing the Prophet during a hard period."},{"prompt":"The surah closes with an instruction to:","options":["Rest permanently","Keep striving and turn to God","Travel abroad","Remain silent"],"correct":1,"explain":"It closes with a rhythm of continued effort followed by devotion."}]'::jsonb),
(93, 'سُورَة الضحى', 'Ad-Duha', 'The Morning Hours', 11, 'Meccan', 'Ad-Duha reassures the Prophet during a pause in revelation, recalling how he was cared for as an orphan and reminding him he hasn''t been abandoned.', '["It''s traditionally linked to a period when revelation paused, leaving the Prophet uncertain and prompting some to suggest he''d been forsaken.","It recalls specific details of his early life — being an orphan, being found in need, and being guided.","It closes with direct instructions on how to treat orphans and those in need, tying personal history to present conduct."]'::jsonb, '["The surah opens with an oath by the morning and the night, then reassures the Prophet that he hasn''t been abandoned or hated by God, despite the pause in revelation.","It recalls how he was cared for through difficult early circumstances, then instructs him to extend that same care outward — to orphans and those who ask for help."]'::jsonb, 'This surah is often read as a model for turning one''s own experience of being helped into a reason to help others.', '[{"prompt":"How many verses does Ad-Duha have?","options":["8","11","14","19"],"correct":1,"explain":"Ad-Duha has 11 verses."},{"prompt":"Ad-Duha is traditionally linked to which period?","options":["The conquest of Makkah","A pause in revelation","The Prophet''s birth","A trade journey"],"correct":1,"explain":"It''s linked to a period when revelation paused, causing uncertainty."},{"prompt":"What does the surah open with an oath by?","options":["The morning and the night","The sea and the mountains","The stars and moon","Fire and water"],"correct":0,"explain":"It opens with an oath by the morning hours and the night."},{"prompt":"The surah recalls the Prophet''s early life as:","options":["A wealthy merchant","An orphan who was found and guided","A soldier","A traveler"],"correct":1,"explain":"It recalls him being an orphan who was cared for and guided."},{"prompt":"The surah closes by instructing care toward:","options":["Rulers and merchants","Orphans and those who ask for help","Soldiers only","Poets"],"correct":1,"explain":"It closes with direct instructions to care for orphans and those in need."}]'::jsonb),
(92, 'سُورَة الليل', 'Al-Layl', 'The Night', 21, 'Meccan', 'Al-Layl contrasts night and day, then describes two very different paths people take — one of giving and God-consciousness, the other of withholding and self-sufficiency.', '["It opens with oaths by the night, the day, and the creation of male and female — pairing natural and human contrasts together.","It describes effort as leading toward different outcomes depending on the path chosen, not a fixed destiny regardless of choice.","It closes by describing the most God-conscious person as one who gives their wealth to purify themselves, without expecting anything in return."]'::jsonb, '["The surah splits people into two groups: those who give, are conscious of God, and affirm goodness, versus those who withhold, feel self-sufficient, and deny goodness.","It states each group is eased toward the path that matches their choices — framing the two outcomes as a consequence of direction taken, not random chance."]'::jsonb, 'A surah often reflected on for its clear framing of generosity versus self-interest as two genuinely different life directions.', '[{"prompt":"How many verses does Al-Layl have?","options":["11","15","21","25"],"correct":2,"explain":"Al-Layl has 21 verses."},{"prompt":"What does the surah open with an oath by?","options":["The night, the day, and male and female","Rivers and seas","Mountains and stars","Fire and smoke"],"correct":0,"explain":"It opens with oaths by the night, the day, and the creation of male and female."},{"prompt":"The surah describes two paths based on:","options":["Wealth alone","Giving versus withholding, God-consciousness versus self-sufficiency","Geography","Family lineage"],"correct":1,"explain":"It contrasts giving and God-consciousness with withholding and self-sufficiency."},{"prompt":"According to the surah, each person is eased toward:","options":["A fixed, unchosen fate","The path that matches their own choices","Wealth regardless of effort","Nothing in particular"],"correct":1,"explain":"The surah frames outcomes as flowing from the direction a person chooses."},{"prompt":"The most God-conscious person is described as one who:","options":["Hoards wealth","Gives their wealth to purify themselves","Travels often","Avoids people"],"correct":1,"explain":"That person gives their wealth to purify themselves, expecting nothing in return."}]'::jsonb),
(91, 'سُورَة الشمس', 'Ash-Shams', 'The Sun', 15, 'Meccan', 'Ash-Shams opens with a striking series of oaths — by the sun, moon, day, night, sky, earth, and soul — before turning to the theme of the soul''s purification or corruption.', '["It contains one of the longest chains of consecutive oaths in the Quran, seven of them before the main point arrives.","It states the soul has been shown both its wickedness and its righteousness — a built-in capacity to recognize both.","It closes by recounting the story of the people of Thamud and the she-camel, as an example of a community that chose corruption."]'::jsonb, '["The surah''s long opening chain of oaths builds toward a single statement: that success belongs to those who purify their soul, and loss belongs to those who corrupt it.","It then illustrates that idea concretely with the story of Thamud, a people who defied a clear warning tied to the she-camel and faced consequence as a result."]'::jsonb, 'The story of Thamud referenced here appears in more detail elsewhere in the Quran; this surah gives only its brief, illustrative form.', '[{"prompt":"How many verses does Ash-Shams have?","options":["11","15","19","22"],"correct":1,"explain":"Ash-Shams has 15 verses."},{"prompt":"How many oaths does the surah open with before its main point?","options":["Two","Four","Seven","Ten"],"correct":2,"explain":"It contains seven consecutive oaths before arriving at its main statement."},{"prompt":"According to the surah, the soul has been shown:","options":["Only wickedness","Only righteousness","Both its wickedness and righteousness","Neither"],"correct":2,"explain":"The soul is described as having been shown both capacities."},{"prompt":"The surah closes with the story of which people?","options":["The people of Thamud","The people of Makkah","The people of Madinah","The people of Sheba"],"correct":0,"explain":"It closes recounting the story of Thamud and the she-camel."},{"prompt":"According to the surah, success belongs to those who:","options":["Accumulate wealth","Purify their soul","Travel widely","Remain silent"],"correct":1,"explain":"Success is tied to purifying the soul; loss to corrupting it."}]'::jsonb),
(90, 'سُورَة البلد', 'Al-Balad', 'The City', 20, 'Meccan', 'Al-Balad swears by "this city" — understood as Makkah — and reflects on human struggle, before describing the "steep path" of freeing captives and feeding the needy.', '["\"This city\" in its opening oath is widely understood to be Makkah, tying the surah closely to its place of revelation.","It describes human life as one of continuous toil and struggle by nature.","It names the \"steep path\" specifically as freeing a slave and feeding the hungry during a time of hardship — concrete rather than abstract acts."]'::jsonb, '["The surah opens by swearing by the city and by human parentage, then states plainly that humanity was created into struggle.","It then poses the \"steep path\" as the meaningful response to that struggle — specific acts like freeing captives and feeding an orphan or a person in need during hardship, paired with belief and patience."]'::jsonb, 'A useful surah for grounding the idea that meaningful faith shows up in concrete acts, not abstract sentiment alone.', '[{"prompt":"How many verses does Al-Balad have?","options":["15","20","25","30"],"correct":1,"explain":"Al-Balad has 20 verses."},{"prompt":"\"This city\" in the surah''s opening oath is understood to be:","options":["Madinah","Makkah","Jerusalem","Damascus"],"correct":1,"explain":"It''s widely understood as a reference to Makkah."},{"prompt":"According to the surah, human life is inherently one of:","options":["Ease","Struggle and toil","Isolation","Wealth"],"correct":1,"explain":"The surah states humanity was created into struggle."},{"prompt":"The \"steep path\" includes which specific acts?","options":["Trading and farming","Freeing captives and feeding the needy","Building monuments","Writing poetry"],"correct":1,"explain":"It names freeing a slave and feeding the hungry during hardship."},{"prompt":"Where was Al-Balad revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Balad is a Meccan surah."}]'::jsonb),
(89, 'سُورَة الفجر', 'Al-Fajr', 'The Dawn', 30, 'Meccan', 'Al-Fajr opens with an oath by the dawn and ten nights, recounts the fate of destroyed civilizations, and closes with the image of a peaceful soul returning to its Lord.', '["It recounts three destroyed peoples in sequence — Aad, Thamud, and Pharaoh — as examples of arrogance meeting consequence.","It directly criticizes love of wealth and neglect of orphans and the poor, similar in theme to some other short surahs.","Its closing verses, describing a soul at peace returning to its Lord, are widely known and often recited in the context of death and remembrance."]'::jsonb, '["The surah''s opening oaths point toward specific times, before shifting into historical example: the destruction of Aad, Thamud, and Pharaoh''s people, all of whom transgressed despite their strength.","It then critiques the tendency to equate wealth with honor and poverty with disgrace, before closing with one of the Quran''s most recognized descriptions of a contented soul''s return to God."]'::jsonb, 'Its closing verses are frequently referenced in the context of death and remembrance, so this surah is often approached with particular care.', '[{"prompt":"How many verses does Al-Fajr have?","options":["20","25","30","35"],"correct":2,"explain":"Al-Fajr has 30 verses."},{"prompt":"Which three peoples are recounted in the surah?","options":["Aad, Thamud, and Pharaoh''s people","Quraysh, Thamud, and Aad","Bani Israel, Aad, and Pharaoh","Thamud, Sheba, and Aad"],"correct":0,"explain":"The surah recounts Aad, Thamud, and Pharaoh''s people as examples."},{"prompt":"What does the surah criticize regarding wealth?","options":["Trading it","Equating it with honor while equating poverty with disgrace","Sharing it","Investing it"],"correct":1,"explain":"It critiques the assumption that wealth means honor and poverty means disgrace."},{"prompt":"The surah''s well-known closing image describes:","options":["A trade caravan","A peaceful soul returning to its Lord","A military victory","A wedding"],"correct":1,"explain":"Its closing verses describe a soul at peace returning to God."},{"prompt":"Where was Al-Fajr revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Fajr is a Meccan surah."}]'::jsonb),
(88, 'سُورَة الغاشية', 'Al-Ghashiyah', 'The Overwhelming', 26, 'Meccan', 'Al-Ghashiyah describes the Day of Judgment as "the overwhelming event," contrasting faces of despair and joy before pointing to everyday signs in creation.', '["Its name, \"the overwhelming,\" refers directly to the Day of Judgment covering everything.","It describes two contrasting groups of faces — humbled and weary versus joyful and pleased — based on their outcome.","It closes by pointing to ordinary things — camels, the sky, mountains, the earth — as signs worth reflecting on."]'::jsonb, '["The surah opens by asking whether \"the overwhelming event\" has reached the listener, then describes two very different outcomes through the imagery of faces — one exhausted and toiling even in punishment, the other content in a beautiful garden.","It then shifts tone, inviting reflection on ordinary creation — how a camel is made, how the sky is raised, how mountains are set firm — as accessible evidence worth noticing."]'::jsonb, 'Its closing shift toward everyday signs is often highlighted as an example of the Quran connecting grand themes to ordinary, observable things.', '[{"prompt":"How many verses does Al-Ghashiyah have?","options":["19","22","26","30"],"correct":2,"explain":"Al-Ghashiyah has 26 verses."},{"prompt":"What does \"Al-Ghashiyah\" refer to?","options":["The overwhelming Day of Judgment","A river","A mountain range","A trade route"],"correct":0,"explain":"\"Al-Ghashiyah\" means \"the overwhelming,\" referring to Judgment Day."},{"prompt":"The surah contrasts two groups through the imagery of:","options":["Clothing","Faces","Homes","Animals"],"correct":1,"explain":"It contrasts humbled, weary faces with joyful, content ones."},{"prompt":"Which of these is NOT among the signs the surah points to?","options":["Camels","The sky","Mountains","Trade caravans"],"correct":3,"explain":"The surah points to camels, the sky, mountains, and the earth — not trade caravans."},{"prompt":"Where was Al-Ghashiyah revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Ghashiyah is a Meccan surah."}]'::jsonb),
(87, 'سُورَة الأعلى', 'Al-A''la', 'The Most High', 19, 'Meccan', 'Al-A''la opens by glorifying God''s name, touches on the ease of the message being conveyed, and compares the fleeting nature of this life to what lasts beyond it.', '["It opens with the instruction to glorify \"the name of your Lord, the Most High.\"","It states the Prophet will be taught in a way that isn''t forgotten, describing ease in how the message is delivered.","Its closing verses note that its core message appears in earlier scriptures too, naming Abraham and Moses specifically."]'::jsonb, '["The surah moves from praising God as the one who creates, proportions, and guides, to reassuring the Prophet about the process of receiving and retaining revelation.","It closes by contrasting people''s preference for the immediate life with the reality that the hereafter is better and more lasting, then notes this same idea appeared in earlier scriptures given to Abraham and Moses."]'::jsonb, 'Its closing reference to earlier scriptures is a useful entry point for understanding how the Quran positions itself in relation to previous revelations.', '[{"prompt":"How many verses does Al-A''la have?","options":["12","19","25","30"],"correct":1,"explain":"Al-A''la has 19 verses."},{"prompt":"The surah opens with an instruction to:","options":["Travel","Glorify the name of the Most High","Fast","Trade fairly"],"correct":1,"explain":"It opens instructing to glorify God''s name, the Most High."},{"prompt":"The surah reassures the Prophet about:","options":["Wealth","Retaining what he''s taught","Travel plans","Family matters"],"correct":1,"explain":"It reassures him that he''ll be taught in a way that isn''t forgotten."},{"prompt":"Which two prophets are named in its closing verses?","options":["Abraham and Moses","Noah and Jesus","Adam and Joseph","David and Solomon"],"correct":0,"explain":"The closing verses name Abraham and Moses specifically."},{"prompt":"The surah contrasts this life with:","options":["A trade journey","The hereafter, described as better and lasting","A dream","Nothing in particular"],"correct":1,"explain":"It contrasts the immediate life with the more lasting hereafter."}]'::jsonb),
(86, 'سُورَة الطارق', 'At-Tariq', 'The Morning Star', 17, 'Meccan', 'At-Tariq opens with an oath by "the night star," reflects on how each person is watched over, and affirms the ability to bring people back after death.', '["\"Tariq\" refers to something that appears at night, understood here as a piercing star.","It describes every soul as having a protector or guardian watching over it.","It uses the process of human reproduction as evidence for the ability to resurrect — pointing to origin as proof of capability."]'::jsonb, '["The surah opens with the striking image of a piercing night star, then makes the point that every soul has something watching over it.","It moves to a reflection on where a person comes from — a fluid emerging from within the body — as an argument for God''s power to bring that same person back after death, since the origin was itself a remarkable act."]'::jsonb, 'A short surah often discussed for how it uses natural processes as accessible evidence for larger theological claims.', '[{"prompt":"How many verses does At-Tariq have?","options":["11","17","22","28"],"correct":1,"explain":"At-Tariq has 17 verses."},{"prompt":"What does \"Tariq\" refer to?","options":["A piercing night star","A river","A mountain","A desert wind"],"correct":0,"explain":"\"Tariq\" refers to something appearing at night, understood as a piercing star."},{"prompt":"According to the surah, every soul has:","options":["No protector","A protector or guardian watching over it","Complete independence","A fixed fate regardless of choice"],"correct":1,"explain":"The surah states every soul has something watching over it."},{"prompt":"The surah points to what as evidence for resurrection?","options":["The stars","The process of human reproduction","Trade routes","Mountains"],"correct":1,"explain":"It uses the origin of human life as an argument for the power to bring it back."},{"prompt":"Where was At-Tariq revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"At-Tariq is a Meccan surah."}]'::jsonb),
(85, 'سُورَة البروج', 'Al-Buruj', 'The Mansions of the Stars', 22, 'Meccan', 'Al-Buruj swears by the sky''s constellations, recounts the persecution of believers by "companions of the pit," and affirms God''s enduring power and the preserved nature of the Quran.', '["\"Buruj\" refers to the great constellations or star-formations in the sky, named in its opening oath.","It recounts a historical episode of believers being persecuted through fire by a hostile group known as the \"companions of the pit.\"","Its closing verse describes the Quran as preserved on a \"guarded tablet,\" a phrase often referenced regarding the Quran''s preservation over time."]'::jsonb, '["The surah opens with cosmic oaths before turning to a specific historical account: a group of believers persecuted and burned for their faith by opponents who then watched the suffering.","It affirms that such cruelty doesn''t go unanswered, pointing to God''s power and forgiveness, before closing with a statement about the Quran''s own preserved, protected status."]'::jsonb, 'The historical episode referenced here involves real persecution and suffering; it''s worth approaching with the same seriousness as other accounts of hardship in the Quran.', '[{"prompt":"How many verses does Al-Buruj have?","options":["16","22","28","34"],"correct":1,"explain":"Al-Buruj has 22 verses."},{"prompt":"What does \"Buruj\" refer to?","options":["Constellations or star-formations","Rivers","Mountains","Trade caravans"],"correct":0,"explain":"\"Buruj\" refers to the great constellations in the sky."},{"prompt":"The surah recounts persecution by whom?","options":["The companions of the pit","Quraysh traders","A trade caravan","Farmers"],"correct":0,"explain":"It recounts believers persecuted by the so-called \"companions of the pit.\""},{"prompt":"The surah''s closing verse describes the Quran as:","options":["Forgotten over time","Preserved on a guarded tablet","Written only in one copy","Open to constant change"],"correct":1,"explain":"It closes describing the Quran as preserved on a guarded tablet."},{"prompt":"Where was Al-Buruj revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Buruj is a Meccan surah."}]'::jsonb),
(84, 'سُورَة الانشقاق', 'Al-Inshiqaq', 'The Sundering', 25, 'Meccan', 'Al-Inshiqaq describes the sky splitting apart at the Day of Judgment, deeds being received in the right or left hand, and calls people to reflect on the effort-filled stages of their lives.', '["It describes the sky \"splitting\" and obeying its Lord as one of several Judgment Day images used across short surahs.","It describes deeds being handed to people in their right hand (a sign of ease) or behind their back (a sign of difficulty).","It states people move \"stage by stage,\" often understood as a reference to life''s changing phases from conception to death and beyond."]'::jsonb, '["The surah opens with the sky splitting apart and the earth being flattened out, obeying its Lord completely — imagery of total, willing submission in creation.","It then describes two different receptions of one''s record of deeds, before calling attention to how every person moves through effort and stages toward an eventual meeting with their Lord."]'::jsonb, 'The imagery of receiving one''s record in the right or left hand appears across several Quran chapters and is often studied together for fuller context.', '[{"prompt":"How many verses does Al-Inshiqaq have?","options":["19","25","30","36"],"correct":1,"explain":"Al-Inshiqaq has 25 verses."},{"prompt":"What does the surah describe the sky doing?","options":["Splitting apart and obeying its Lord","Turning to stone","Disappearing entirely","Filling with clouds"],"correct":0,"explain":"It describes the sky splitting and obeying its Lord completely."},{"prompt":"Receiving one''s deeds in the right hand is a sign of:","options":["Difficulty","Ease","Neutrality","Nothing significant"],"correct":1,"explain":"Receiving the record in the right hand signals ease."},{"prompt":"The phrase \"stage by stage\" is often understood to refer to:","options":["Trade seasons","Life''s changing phases","Seasons of the year","Building stages"],"correct":1,"explain":"It''s often understood as referring to the changing phases of a person''s life."},{"prompt":"Where was Al-Inshiqaq revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Inshiqaq is a Meccan surah."}]'::jsonb),
(83, 'سُورَة المطففين', 'Al-Mutaffifin', 'Defrauding', 36, 'Meccan', 'Al-Mutaffifin condemns those who cheat when measuring or weighing goods, and contrasts the recorded fate of the wicked with that of the righteous.', '["Its name refers specifically to those who shortchange others in trade — giving less than full measure while demanding full measure for themselves.","It names two contrasting records: \"Sijjin\" for the wicked and \"Illiyyin\" for the righteous.","It describes the wicked mocking believers in this life, then reverses that scene, describing believers observing the outcome from a position of ease."]'::jsonb, '["The surah opens with a direct warning to those who cheat in trade — demanding full measure from others while shortchanging them in return — tying commercial honesty to accountability before God.","It then describes two separate destinies recorded in two different registers, closing with a scene where the mockery the righteous once endured in this life is reversed in the next."]'::jsonb, 'This surah pairs commercial fairness directly with faith, making it a frequently cited reference point on honesty in trade and business.', '[{"prompt":"How many verses does Al-Mutaffifin have?","options":["22","28","36","42"],"correct":2,"explain":"Al-Mutaffifin has 36 verses."},{"prompt":"What does \"Al-Mutaffifin\" refer to?","options":["Those who cheat in measuring or weighing","Travelers","Farmers","Poets"],"correct":0,"explain":"The name refers to those who defraud others in trade measurements."},{"prompt":"What are the two contrasting records named in the surah?","options":["Sijjin and Illiyyin","Kawthar and Masad","Falaq and Nas","Duha and Sharh"],"correct":0,"explain":"\"Sijjin\" is named for the wicked and \"Illiyyin\" for the righteous."},{"prompt":"The surah describes the wicked doing what to believers in this life?","options":["Ignoring them","Mocking them","Helping them","Avoiding them entirely"],"correct":1,"explain":"It describes the wicked mocking believers, a scene later reversed."},{"prompt":"Where was Al-Mutaffifin revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Mutaffifin is a Meccan surah."}]'::jsonb),
(82, 'سُورَة الإنفطار', 'Al-Infitar', 'The Cleaving', 19, 'Meccan', 'Al-Infitar describes the sky cleaving apart, stars scattering, and graves being overturned — a rapid sequence of Judgment Day imagery, alongside a mention of recording angels.', '["It moves through several cosmic events in quick succession — sky cleaving, stars scattering, seas bursting forth, graves overturned.","It mentions \"noble recorders\" — angels who record what each person does.","It asks directly what has deceived people about their generous Lord, given how carefully they were shaped."]'::jsonb, '["The surah''s opening verses move rapidly through a sequence of cosmic unraveling, building a sense of sudden, total upheaval.","It then turns personal, asking what led a person to be careless about their Lord despite being carefully created and shaped, and reminding that every action is being recorded by appointed angels."]'::jsonb, 'Its rapid sequence of imagery is a good example of how short Meccan surahs often build urgency through pace as much as content.', '[{"prompt":"How many verses does Al-Infitar have?","options":["14","19","24","30"],"correct":1,"explain":"Al-Infitar has 19 verses."},{"prompt":"What does the surah describe in quick succession?","options":["Trade caravans","Sky cleaving, stars scattering, graves overturned","Farming seasons","Wedding customs"],"correct":1,"explain":"It moves rapidly through several cosmic Judgment Day events."},{"prompt":"Who are the \"noble recorders\" mentioned in the surah?","options":["Human scribes","Angels who record each person''s actions","Trade witnesses","Prophets"],"correct":1,"explain":"They are angels appointed to record what each person does."},{"prompt":"The surah asks what has deceived people about:","options":["Their wealth","Their generous Lord","Their neighbors","Their ancestors"],"correct":1,"explain":"It asks what deceived people about their generous, careful Creator."},{"prompt":"Where was Al-Infitar revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Al-Infitar is a Meccan surah."}]'::jsonb),
(81, 'سُورَة التكوير', 'At-Takwir', 'The Overthrowing', 29, 'Meccan', 'At-Takwir opens with vivid cosmic imagery — the sun folded up, stars falling — before affirming the Prophet''s honest character and the trustworthy nature of the angel who brought revelation.', '["Its opening verses list roughly a dozen cosmic and natural upheavals in rapid succession, one of the most vivid such sequences in the Quran.","It defends the Quran against accusations by clarifying it is not the words of a poet or a soothsayer.","It affirms that the angel bringing revelation, understood as Gabriel, is trustworthy and was seen clearly by the Prophet."]'::jsonb, '["The surah''s opening builds an intense picture of cosmic unraveling — the sun, stars, mountains, seas, and more, all undergoing dramatic change — before shifting to the moment souls are paired with their deeds.","It then defends the source of the revelation directly, describing the messenger angel as trustworthy and firmly rejecting claims that the message came from a poet or was influenced by madness."]'::jsonb, 'Its vivid opening imagery is often studied alongside similarly styled surahs from the same phase of revelation for comparison.', '[{"prompt":"How many verses does At-Takwir have?","options":["19","24","29","35"],"correct":2,"explain":"At-Takwir has 29 verses."},{"prompt":"The surah''s opening describes:","options":["A single calm scene","A rapid sequence of cosmic upheavals","A trade journey","A wedding celebration"],"correct":1,"explain":"It opens with roughly a dozen cosmic and natural upheavals in quick succession."},{"prompt":"The surah defends the Quran against being called:","options":["Too short","The words of a poet or soothsayer","Too difficult","Unoriginal"],"correct":1,"explain":"It clarifies the Quran is not the work of a poet or soothsayer."},{"prompt":"The trustworthy messenger angel referenced is understood to be:","options":["Michael","Gabriel","Israfil","Azrael"],"correct":1,"explain":"The angel is widely understood to be Gabriel."},{"prompt":"Where was At-Takwir revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"At-Takwir is a Meccan surah."}]'::jsonb),
(80, 'سُورَة عبس', 'Abasa', 'He Frowned', 42, 'Meccan', 'Abasa recounts a moment when the Prophet, engaged with prominent Makkan figures, briefly turned from a blind man who''d come seeking guidance — and the surah gently corrects the moment.', '["Its name, \"He Frowned,\" refers to the opening scene the surah addresses directly.","It''s one of the clearer examples in the Quran of a moment involving the Prophet being addressed and corrected.","After the opening scene, it shifts into reflections on human creation, sustenance, and the Day of Judgment."]'::jsonb, '["The surah opens by describing someone turning away from a blind man who came earnestly seeking guidance, while being occupied with others who showed less genuine interest.","It gently redirects attention toward what matters — sincere seeking over apparent status — before moving into a wider reflection on how carefully each person''s provision and creation was arranged."]'::jsonb, 'This passage is often discussed as an example of humility and correction within the Prophet''s own story, approached with care and respect rather than criticism.', '[{"prompt":"How many verses does Abasa have?","options":["28","35","42","50"],"correct":2,"explain":"Abasa has 42 verses."},{"prompt":"What does \"Abasa\" mean?","options":["He Frowned","The Cave","The Table","The Dawn"],"correct":0,"explain":"\"Abasa\" means \"he frowned,\" referring to the surah''s opening scene."},{"prompt":"The opening scene involves turning away from:","options":["A trader","A blind man seeking guidance","A soldier","A poet"],"correct":1,"explain":"It describes a moment of turning from a blind man who came seeking guidance."},{"prompt":"After its opening scene, the surah shifts to reflect on:","options":["Trade agreements","Human creation and sustenance","Farming techniques","Poetry"],"correct":1,"explain":"It moves into reflection on how carefully human creation and provision were arranged."},{"prompt":"Where was Abasa revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"Abasa is a Meccan surah."}]'::jsonb),
(79, 'سُورَة النازعات', 'An-Nazi''at', 'Those Who Drag Forth', 46, 'Meccan', 'An-Nazi''at opens with an oath tied to angels connected to souls at the moment of death, recounts the story of Pharaoh and Moses, and closes with Judgment Day imagery.', '["Its opening oaths are widely understood to refer to angels involved in taking and releasing souls.","It retells the confrontation between Moses and Pharaoh in a condensed form, focused on Pharaoh''s arrogance and downfall.","It closes by noting that people often ask when the Judgment Hour will come, and redirects that the timing isn''t the Prophet''s concern to answer."]'::jsonb, '["The surah opens with a sequence of oaths connected to the process of death, before shifting into recounting Moses being sent to Pharaoh, who denied the message and claimed ultimate authority for himself.","It closes by addressing curiosity about exactly when the Hour will arrive, making clear that warning people is the task at hand — not predicting a specific date."]'::jsonb, 'The story of Moses and Pharaoh appears across many parts of the Quran; this version is condensed, so exploring the fuller narrative elsewhere can add useful context.', '[{"prompt":"How many verses does An-Nazi''at have?","options":["32","39","46","52"],"correct":2,"explain":"An-Nazi''at has 46 verses."},{"prompt":"The surah''s opening oaths are understood to refer to:","options":["Angels connected to souls at death","Trade caravans","Mountains","Rivers"],"correct":0,"explain":"They''re widely understood to reference angels involved in taking and releasing souls."},{"prompt":"Which historical confrontation does the surah recount?","options":["Moses and Pharaoh","Abraham and Nimrod","Noah and his people","Joseph and his brothers"],"correct":0,"explain":"It recounts the confrontation between Moses and Pharaoh."},{"prompt":"What does Pharaoh claim in the surah?","options":["He seeks guidance","Ultimate authority for himself","He is a trader","He is a poet"],"correct":1,"explain":"Pharaoh is described claiming ultimate authority for himself."},{"prompt":"How does the surah respond to questions about the Hour''s timing?","options":["Gives a specific date","States it isn''t the Prophet''s task to specify","Ignores the question entirely","Claims it already happened"],"correct":1,"explain":"It makes clear that warning people is the task, not predicting the exact timing."}]'::jsonb),
(78, 'سُورَة النبأ', 'An-Naba', 'The Tidings', 40, 'Meccan', 'An-Naba opens Juz Amma (the final section of the Quran), asking about "the great news" people were disputing over — the Day of Judgment — before describing creation itself as a set of signs.', '["It marks the beginning of the 30th and final juz (section) of the Quran, a common starting point for memorization.","It opens by referencing a dispute among people over \"the great tidings,\" understood as the reality of resurrection and judgment.","It moves through a list of everyday elements of creation — earth, mountains, sleep, night, day, sky, rain — presented as signs worth noticing."]'::jsonb, '["The surah opens by naming a disagreement people had over \"the great news,\" before affirming that its reality will become clear regardless of the dispute.","It lists ordinary features of the world — the earth spread out, mountains as stakes, sleep as rest, rain producing grain — as evidence pointing toward a deliberate Creator, before shifting into vivid description of the Day of Judgment itself for those who denied it."]'::jsonb, 'As the opening surah of Juz Amma, it''s a natural anchor point — many learners begin memorizing this section from here.', '[{"prompt":"How many verses does An-Naba have?","options":["30","35","40","45"],"correct":2,"explain":"An-Naba has 40 verses."},{"prompt":"An-Naba marks the beginning of which section of the Quran?","options":["The first juz","The 15th juz","The 30th (final) juz","The final surah only"],"correct":2,"explain":"It opens Juz Amma, the 30th and final section of the Quran."},{"prompt":"\"The great tidings\" mentioned at the opening refers to:","options":["A trade agreement","The reality of resurrection and judgment","A historical battle","A royal announcement"],"correct":1,"explain":"It refers to the disputed reality of the Day of Judgment."},{"prompt":"Which of these is NOT listed among the surah''s everyday signs of creation?","options":["The earth spread out","Mountains as stakes","Sleep as rest","Trade caravans"],"correct":3,"explain":"The surah lists earth, mountains, sleep, night, day, sky, and rain — not trade caravans."},{"prompt":"Where was An-Naba revealed?","options":["Makkah (Meccan)","Madinah (Medinan)"],"correct":0,"explain":"An-Naba is a Meccan surah."}]'::jsonb)
